<?php
if (!($pdo instanceof PDO)) { echo '<section class="panel"><p>Hubungkan database untuk membuat laporan.</p></section>'; return; }
$summary = $pdo->query('SELECT COUNT(*) AS analysis_count, COUNT(DISTINCT item_id) AS item_count, COALESCE(AVG(eoq_quantity), 0) AS avg_eoq, COALESCE(SUM(relevant_total_cost), 0) AS total_cost FROM eoq_analyses')->fetch();
$rows = $pdo->query('SELECT a.id, a.analysis_name, a.annual_demand, a.ordering_cost, a.holding_cost, a.eoq_quantity, a.orders_per_year, a.order_interval_days, a.ordering_cost_total, a.holding_cost_total, a.relevant_total_cost, a.created_at, i.item_code, i.name AS item_name, i.unit FROM eoq_analyses a JOIN items i ON i.id = a.item_id ORDER BY a.created_at DESC, a.id DESC')->fetchAll();
?>
<section class="page-intro"><div><h2>Laporan EOQ</h2><p>Rekap hasil analisis yang tersimpan di database.</p></div><a class="button button-primary" href="index.php?page=reports&export=csv">Unduh CSV</a></section>
<section class="stats-grid"><article class="stat-card"><span>Jumlah analisis</span><strong><?= number_format((int) $summary['analysis_count']) ?></strong></article><article class="stat-card"><span>Barang yang dianalisis</span><strong><?= number_format((int) $summary['item_count']) ?></strong></article><article class="stat-card"><span>Rata-rata EOQ</span><strong><?= number_id($summary['avg_eoq']) ?></strong></article><article class="stat-card"><span>Total biaya relevan</span><strong class="currency"><?= h(rupiah($summary['total_cost'])) ?></strong></article></section>
<section class="panel"><div class="panel-heading"><div><h3>Rekapitulasi analisis</h3><p><?= count($rows) ?> baris data</p></div><a href="index.php?page=history">Buka riwayat →</a></div>
<?php if ($rows): ?><div class="table-wrap"><table><thead><tr><th>Tanggal</th><th>Barang</th><th>D</th><th>S</th><th>H</th><th>EOQ</th><th>Order/tahun</th><th>Biaya relevan</th></tr></thead><tbody><?php foreach ($rows as $row): ?><tr><td><?= h(date('d-m-Y', strtotime($row['created_at']))) ?></td><td><?= h($row['item_code'] . ' · ' . $row['item_name']) ?></td><td><?= number_id($row['annual_demand']) ?></td><td><?= h(rupiah($row['ordering_cost'])) ?></td><td><?= h(rupiah($row['holding_cost'])) ?></td><td><?= number_id($row['eoq_quantity']) ?> <?= h($row['unit']) ?></td><td><?= number_id($row['orders_per_year']) ?></td><td><?= h(rupiah($row['relevant_total_cost'])) ?></td></tr><?php endforeach; ?></tbody></table></div><?php else: ?><div class="empty-state"><strong>Belum ada data laporan.</strong><p>Laporan akan terisi setelah ada analisis yang disimpan.</p></div><?php endif; ?>
</section>
